import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import { URL } from 'url';

const app = express();

// Configuration from Kubernetes ConfigMap
const OAUTH_CONFIG = {
  clientId: process.env.OAUTH_CLIENT_ID || 'k8s-service-auth',
  clientSecret: process.env.OAUTH_CLIENT_SECRET || '',
  authorizeEndpoint: 'https://idp.internal.corp/oauth2/authorize',
  tokenEndpoint: 'https://idp.internal.corp/oauth2/token',
  allowedRedirectDomains: ['app.corp.internal', 'dashboard.corp.internal', 'portal.corp.internal'],
  serviceBaseUrl: process.env.SERVICE_BASE_URL || 'https://gateway.corp.internal'
};

// State store (in production, backed by Redis via K8s service)
const stateStore = new Map<string, { redirectUri: string; createdAt: number; nonce: string }>();

// Cleanup expired states every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, value] of stateStore.entries()) {
    if (now - value.createdAt > 600000) stateStore.delete(key);
  }
}, 300000);

function generateSecureState(): string {
  return crypto.randomBytes(32).toString('hex');
}

function normalizeRedirectUri(uri: string): string {
  // Normalize the URI to prevent encoding-based bypasses
  try {
    const decoded = decodeURIComponent(uri);
    return decoded.toLowerCase().trim();
  } catch {
    return uri.toLowerCase().trim();
  }
}

function extractHostFromUri(uri: string): string | null {
  try {
    // Handle protocol-relative URLs
    const urlToParse = uri.startsWith('//') ? `https:${uri}` : uri;
    const parsed = new URL(urlToParse);
    return parsed.hostname;
  } catch {
    return null;
  }
}

function isDomainAllowed(hostname: string): boolean {
  // Check if the hostname matches or is a subdomain of allowed domains
  const normalizedHost = hostname.toLowerCase();
  return OAUTH_CONFIG.allowedRedirectDomains.some(allowed => {
    return normalizedHost === allowed || normalizedHost.endsWith('.' + allowed);
  });
}

function validateRedirectUri(redirectUri: string): boolean {
  if (!redirectUri) return false;

  const normalized = normalizeRedirectUri(redirectUri);

  // Block javascript: and data: schemes
  if (normalized.startsWith('javascript:') || normalized.startsWith('data:')) {
    return false;
  }

  // Must be absolute URL with https
  if (!normalized.startsWith('https://') && !normalized.startsWith('https%3a')) {
    // Allow relative paths that will resolve to our service
    if (normalized.startsWith('/') && !normalized.startsWith('//')) {
      return true;
    }
    return false;
  }

  const host = extractHostFromUri(normalized);
  if (!host) return false;

  return isDomainAllowed(host);
}

// Initiate OAuth flow
app.get('/auth/login', (req: Request, res: Response) => {
  const redirectUri = (req.query.redirect_uri as string) || `${OAUTH_CONFIG.serviceBaseUrl}/dashboard`;

  if (!validateRedirectUri(redirectUri)) {
    return res.status(400).json({ error: 'Invalid redirect URI' });
  }

  const state = generateSecureState();
  const nonce = crypto.randomBytes(16).toString('hex');

  stateStore.set(state, {
    redirectUri: redirectUri,
    createdAt: Date.now(),
    nonce
  });

  const authUrl = new URL(OAUTH_CONFIG.authorizeEndpoint);
  authUrl.searchParams.set('client_id', OAUTH_CONFIG.clientId);
  authUrl.searchParams.set('response_type', 'code');
  authUrl.searchParams.set('redirect_uri', `${OAUTH_CONFIG.serviceBaseUrl}/auth/callback`);
  authUrl.searchParams.set('state', state);
  authUrl.searchParams.set('scope', 'openid profile email');
  authUrl.searchParams.set('nonce', nonce);

  res.redirect(302, authUrl.toString());
});

// OAuth callback handler
app.get('/auth/callback', async (req: Request, res: Response) => {
  const { code, state, error } = req.query;

  if (error) {
    return res.status(400).json({ error: `OAuth error: ${error}` });
  }

  if (!state || !code) {
    return res.status(400).json({ error: 'Missing required parameters' });
  }

  const storedState = stateStore.get(state as string);
  if (!storedState) {
    return res.status(403).json({ error: 'Invalid or expired state' });
  }

  // Verify state hasn't expired (10 minute window)
  if (Date.now() - storedState.createdAt > 600000) {
    stateStore.delete(state as string);
    return res.status(403).json({ error: 'State expired' });
  }

  stateStore.delete(state as string);

  // In production: exchange code for token via tokenEndpoint
  // For this service, we set a session and redirect
  const sessionToken = crypto.randomBytes(32).toString('hex');

  res.cookie('session', sessionToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    maxAge: 3600000
  });

  // Redirect to the originally requested URI
  const finalRedirect = storedState.redirectUri;

  // Re-validate before redirect (defense in depth)
  if (!validateRedirectUri(finalRedirect)) {
    return res.redirect(302, `${OAUTH_CONFIG.serviceBaseUrl}/dashboard`);
  }

  res.redirect(302, finalRedirect);
});

app.get('/health', (_req: Request, res: Response) => {
  res.json({ status: 'healthy', service: 'oauth-gateway' });
});

app.listen(8080, '0.0.0.0', () => {
  console.log('OAuth gateway listening on :8080');
});

export default app;
